"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["86986"],{81949(e,t,n){n.r(t),n.d(t,{metadata:()=>s,default:()=>m,frontMatter:()=>c,contentTitle:()=>d,toc:()=>l,assets:()=>h});var s=JSON.parse('{"id":"nhcx/v1/api/session/endpoints/session-session-token","title":"Session token","description":"Mints the ABDM gateway session token that every NHCX call carries, from the client ID and secret issued for Milestone 1.","source":"@site/docs/nhcx/v1/api/session/endpoints/session-session-token.mdx","sourceDirName":"nhcx/v1/api/session/endpoints","slug":"/nhcx/v1/api/session/endpoints/session-session-token","permalink":"/docs/pr-10/docs/nhcx/v1/api/session/endpoints/session-session-token","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Session token","sidebar_label":"Session token","sidebar_class_name":"api-method api-method--post","description":"Mints the ABDM gateway session token that every NHCX call carries, from the client ID and secret issued for Milestone 1.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"nhcx-session.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Overview","permalink":"/docs/pr-10/docs/nhcx/v1/api/session/"},"next":{"title":"Overview","permalink":"/docs/pr-10/docs/nhcx/v1/api/eligibility/"}}'),i=n(62540),a=n(43023),o=n(70862),r=JSON.parse('{"id":"session_session_token","module":"Session","moduleId":"session","kind":"operation","method":"POST","path":"/api/hiecm/gateway/v3/sessions","server":"https://dev.abdm.gov.in","servers":[{"url":"https://dev.abdm.gov.in","description":"Sandbox, ABDM session token."},{"url":"https://apis.abdm.gov.in","description":"Production. ABDM\'s published production gateway. Confirm it in your onboarding letter."}],"summary":"Session token","description":"Mints the ABDM gateway session token that every NHCX call carries, from the client ID and secret issued for Milestone 1.\\n\\n### Business purpose\\n\\nThe token does not come from NHCX. It comes from the ABDM gateway, and one token serves every call: the participant service, the use-case endpoints and the status check. Nothing else in this collection works without it, which is why the post-response script below stores it in `token`, so that running this request once arms the rest of the collection.\\n\\n### When to use\\n\\nBefore the first call, and again whenever the token you hold is more than a few minutes old or any call answers `401`. Build against this v3 address.\\n\\n### Preconditions\\n\\n- Milestone 1 is complete and you hold its client ID and secret.\\n- `REQUEST-ID` is a fresh UUID generated for this call.\\n- `TIMESTAMP` is the current time in UTC, ISO 8601 with milliseconds and a trailing `Z`, as in `2026-09-04T06:15:51.975Z`, taken from a synchronised system clock.\\n- `X-CM-ID` is `sbx` on the sandbox.\\n- The body carries `grantType` `client_credentials`, which the v3 address requires.\\n\\n### Postconditions\\n\\nThe gateway returns `accessToken`, `expiresIn`, `refreshToken` and `tokenType` `bearer`. On every NHCX call the token goes in `bearer_auth` as `Bearer <token>`. Some pages and the notification endpoint use `Authorization` instead, so this collection sends both with the same value. The documents put the token\'s life at 300, 1200 and 6000 seconds in different places, so do not rely on any of them.\\n\\n### Common mistakes\\n\\n- Reusing a `REQUEST-ID` copied from an example instead of generating a new one.\\n- A `TIMESTAMP` built by hand or read from a drifted clock, which is refused.\\n- Omitting `grantType`, as older samples do, which the v3 address rejects.\\n- Sending the token without the `Bearer ` prefix, the portal\'s own example of a `401`.\\n- Retrying a `401` with the same token. It fails the same way.\\n- Writing the token or the client secret to a log.\\n\\n### Best practices\\n\\n- Keep the token together with the time you got it, and fetch a new one before a call if it is more than a few minutes old.\\n- On any `401`, get a new token and retry that call once.\\n- Send the token on both `bearer_auth` and `Authorization`.\\n- Keep the clock synchronised with NTP and let a date library format the timestamp.\\n\\n### Related scenario\\n\\nA hospital\'s integration starts its first eligibility check of the day. It posts this request with a new `REQUEST-ID`, the current UTC `TIMESTAMP` and `X-CM-ID` `sbx`, stores the `accessToken` with the time it arrived, and sends it on the check as `bearer_auth: Bearer <token>`. Later a claim call answers `401 Sender is not authorized to execute the operation`. The integration mints a fresh token, retries the claim once, and it goes through.\\n\\n### Specification\\n\\nChapter [Base URLs](/docs/nhcx/v1/getting-started/base-urls) of the NHCX integration specification.","security":[],"headers":[{"name":"REQUEST-ID","required":true,"description":"`REQUEST-ID` is a fresh UUID that you generate for every call. Sending the same one twice is the mistake to avoid; generate it, do not copy it from an example.","example":"<uuid>","type":"string"},{"name":"TIMESTAMP","required":true,"description":"`TIMESTAMP` is the current time in UTC, ISO 8601 with milliseconds and a trailing `Z`, as in `2026-09-04T06:15:51.975Z`. A clock that has drifted will be refused, so take the time from the system rather than constructing it by hand. How to produce it in each language is at the end of this chapter.","example":"<iso timestamp>","type":"string"},{"name":"X-CM-ID","required":true,"description":"`X-CM-ID` names the environment. It is `sbx` on the sandbox. The mirror and the adapter both use lowercase.","example":"sbx","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"clientId","type":"string","required":false,"description":"","encrypted":false},{"name":"clientSecret","type":"string","required":false,"description":"","encrypted":false},{"name":"grantType","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"clientId":"<client id>","clientSecret":"<client secret>","grantType":"client_credentials"},"responses":[{"status":"200","description":"The gateway returns `accessToken`, `expiresIn`, `refreshToken` and `tokenType` `bearer`.","example":{"accessToken":"eyJhbGciOiJSUzI1NiIs...","expiresIn":300,"refreshTokenIn":300,"refreshToken":"eyJhbGciOiJSUzI1NiIs...","tokenType":"bearer"}}],"tag":"Session","tagDescription":"The token does not come from NHCX.","atom":"nhcx.endpoint.session-token","curl":"curl --request POST \\\\\\n  --url https://dev.abdm.gov.in/api/hiecm/gateway/v3/sessions \\\\\\n  --header \'REQUEST-ID: <uuid>\' \\\\\\n  --header \'TIMESTAMP: <iso timestamp>\' \\\\\\n  --header \'X-CM-ID: sbx\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"clientId\\": \\"<client id>\\",\\n  \\"clientSecret\\": \\"<client secret>\\",\\n  \\"grantType\\": \\"client_credentials\\"\\n}\'"}');let c={title:"Session token",sidebar_label:"Session token",sidebar_class_name:"api-method api-method--post",description:"Mints the ABDM gateway session token that every NHCX call carries, from the client ID and secret issued for Milestone 1.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"nhcx-session.yaml",generated:!0},d,h={},l=[];function p(e){return(0,i.jsx)(o.A,{operation:r})}function m(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(p,{...e})}):p(e)}}}]);